mapper.select:
select * from index_params where parentparamno in (
select parentparamno from index_params where paramno in (
select index_no from knowledge_relate_index where supplier_id is not null and knowledge_id in

    #{knowledgeId}

))
union
select * from index_params where paramno in (
select parentparamno from index_params where parentparamno in (select parentparamno from index_params where paramno in (
select index_no from knowledge_relate_index where supplier_id is not null and knowledge_id in

    #{knowledgeId}

)))
union
select * from index_params where paramno in (
select index_no from knowledge_relate_index where supplier_id is null and knowledge_id in

    #{knowledgeId}

)
union
select * from index_params where parentparamno in (
select index_no from knowledge_relate_index where supplier_id is null and knowledge_id in

    #{knowledgeId}

)

WITH RECURSIVE index_sub_tree AS ( SELECT paramno FROM index_params WHERE paramno IN
#{item}
UNION SELECT p.paramno FROM index_params p INNER JOIN index_sub_tree s ON p.parentparamno = s.paramno ) SELECT * FROM index_params WHERE paramno IN (SELECT paramno FROM index_sub_tree) OR parentparamno IN (SELECT paramno FROM index_sub_tree)
